interaction_contract

def region_view(data: pd.DataFrame, selected_region: str) -> pd.DataFrame:
    if selected_region not in set(data["region"]):
        raise ValueError(f"Unknown region: {selected_region}")
    return (
        data.loc[data["region"].eq(selected_region)]
        .groupby("month", as_index=False)["revenue"]
        .sum()
    )


selected = sorted(dashboard["region"].unique())[0]
selected_data = region_view(dashboard, selected)
assert not selected_data.empty
assert selected_data["month"].is_monotonic_increasing
